/// Select notebooks directly or by matching cell languages, with optional additional constraints.
/// The containing protocol representation is [`NotebookDocumentSyncOptions::notebook_selector`].
/// Construction has no side effects: no I/O, messages or applied edits.
///
/// Present constraints within a notebook filter all have to match. Alternative selectors are combined as choices. A notebook-only selector includes all its cells; a cell-only selector includes notebooks containing a matching language.
///
/// # Structure
/// ```text
/// [notebook type / scheme / path]       [cell language]
///                 |                          |
///          [notebook constraint]       [cell constraint]
///                 |                          |
///                 +------- <selector> -------+
///                         /          \
///              [ByNotebook]        [ByCells]
///                         \          /
///                  [matching notebooks + cells]
///                              |
///                      [synchronization scope]
/// ```
///
/// # Examples
/// ```
/// use lspally::server::model::*;
/// let value: NotebookSelector = NotebookSelector::ByNotebook {
///     notebook: Notebook::String("jupyter-notebook".into()),
///     cells: None,
/// };
/// if let NotebookSelector::ByNotebook { notebook, .. } = &value {
///     let _ = notebook;
/// }
/// if let NotebookSelector::ByNotebook { cells, .. } = &value {
///     let _ = cells;
/// }
/// if let NotebookSelector::ByCells { notebook, .. } = &value {
///     let _ = notebook;
/// }
/// if let NotebookSelector::ByCells { cells, .. } = &value {
///     let _ = cells;
/// }
/// ```
#[derive(Debug)]
pub enum NotebookSelector {
    /// Select matching notebooks; absent cell filters synchronize all their cells.
    /// Example: `if let NotebookSelector::ByNotebook { notebook, .. } = &value { let _ = notebook; }`.
    ByNotebook {
        /// Notebook type/filter constraint; when optional and absent, matching cells alone select their
        /// notebooks.
        /// Example: `if let NotebookSelector::ByNotebook { notebook, .. } = &value { let _ = notebook; }`.
        notebook: Notebook,
        /// Cell-language filters; when optional and absent, all cells in the matching notebook
        /// synchronize.
        /// Example: `if let NotebookSelector::ByNotebook { cells, .. } = &value { let _ = cells; }`.
        cells: Option<Vec<NotebookCellSelector>>,
    },
    /// Select notebooks containing matching cell languages, optionally also constrained by notebook.
    /// Example: `if let NotebookSelector::ByCells { notebook, .. } = &value { let _ = notebook; }`.
    ByCells {
        /// Notebook type/filter constraint; when optional and absent, matching cells alone select their
        /// notebooks.
        /// Example: `if let NotebookSelector::ByCells { notebook, .. } = &value { let _ = notebook; }`.
        notebook: Option<Notebook>,
        /// Cell-language filters; when optional and absent, all cells in the matching notebook
        /// synchronize.
        /// Example: `if let NotebookSelector::ByCells { cells, .. } = &value { let _ = cells; }`.
        cells: Vec<NotebookCellSelector>,
    },
}
